using MediatR;using ProjectNet.Application.Abstractions;using ProjectNet.Application.DTOs;namespace ProjectNet.Application.Queries.GetAllProducts;public sealed class GetAllProductsQueryHandler : IRequestHandler<GetAllProductsQuery, IReadOnlyList<ProductDto>> { private readonly IProductRepository _r; public GetAllProductsQueryHandler(IProductRepository r)=>_r=r; public async Task<IReadOnlyList<ProductDto>> Handle(GetAllProductsQuery request, CancellationToken ct){ var products=await _r.GetAllAsync(ct); return products.Select(p=>p.ToDto()).ToList(); } }
